<!-- Navigering/Verktygsfält -->
<div class="no-print sticky top-0 bg-white border-b p-3 flex justify-center gap-4 shadow-sm z-50">
    <button id="btnPrint" type="button" class="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-lg font-medium transition flex items-center gap-2 shadow-md">
        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg>
        Skriv ut / Spara PDF
    </button>
    <button id="btnReset" type="button" class="bg-white hover:bg-gray-50 text-gray-700 px-5 py-2 rounded-lg font-medium transition flex items-center gap-2 border border-gray-300 shadow-sm">
        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"></path><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"></path><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"></path></svg>
        Rensa fält
    </button>
</div>

<form id="gradeForm" class="paper" onsubmit="return false;">
    <div class="text-center mb-8">
        <p class="text-xs font-bold uppercase tracking-widest text-gray-400 mb-1">Officiell Blankett</p>
        <h1 class="text-xl font-bold">Beslut om ändring/rättelse av satt betyg</h1>
        <p class="text-md text-gray-600">Danderyds kommun – <input type="text" placeholder="[Skolans namn]" class="w-auto text-center font-semibold border-b-0 focus:border-b" style="min-width: 150px;"></p>
    </div>

    <div class="section-header">1. Elevuppgifter</div>
    <div class="grid grid-cols-1 md:grid-cols-2 gap-4 mt-2">
        <div>
            <label class="block text-xs font-bold text-gray-500 uppercase">Elev</label>
            <input type="text" name="elev_namn" placeholder="Namn eller Elev-ID">
        </div>
        <div>
            <label class="block text-xs font-bold text-gray-500 uppercase">Klass</label>
            <input type="text" name="klass" placeholder="Fyll i klass">
        </div>
        <div>
            <label class="block text-xs font-bold text-gray-500 uppercase">Kurs / Ämne</label>
            <input type="text" name="amne" placeholder="Fyll i ämne">
        </div>
        <div>
            <label class="block text-xs font-bold text-gray-500 uppercase">Datum för ursprungligt betyg</label>
            <input type="date" name="datum_ursprung">
        </div>
    </div>

    <div class="section-header">2. Typ av ändring</div>
    <div class="space-y-3 mt-2">
        <label class="flex items-start gap-3 cursor-pointer">
            <input type="checkbox" class="w-4 h-4 mt-1 border-gray-300 rounded">
            <span class="text-sm"><span class="font-bold">Rättelse av skrivfel</span> (Skollagen 26 kap. 39 §)</span>
        </label>
        <label class="flex items-start gap-3 cursor-pointer">
            <input type="checkbox" class="w-4 h-4 mt-1 border-gray-300 rounded">
            <span class="text-sm"><span class="font-bold">Ändring av betyg</span> (Skollagen 26 kap. 40 §)</span>
        </label>
    </div>

    <div class="section-header">3. Motivering</div>
    <textarea name="motivering" rows="5" class="mt-1 resize-none text-sm" placeholder="Beskriv omständigheterna och hänvisa till underlag..."></textarea>

    <div class="section-header">4. Beslutsunderlag</div>
    <div class="flex gap-10 mt-2">
        <div class="flex items-baseline gap-2">
            <span class="font-bold text-sm">Ursprungligt betyg:</span>
            <input type="text" class="w-12 text-center font-bold">
        </div>
        <div class="flex items-baseline gap-2">
            <span class="font-bold text-sm">Nytt betyg:</span>
            <input type="text" class="w-12 text-center font-bold text-blue-700">
        </div>
    </div>

    <div class="section-header">5. Underskrifter</div>
    <div class="grid grid-cols-2 gap-x-10 gap-y-10 mt-6 mb-2">
        <div><div class="signature-line font-bold text-[10px] uppercase text-gray-400">Undervisande lärare</div></div>
        <div><div class="signature-line font-bold text-[10px] uppercase text-gray-400">Datum</div></div>
        <div><div class="signature-line font-bold text-[10px] uppercase text-gray-400">Rektor (Kännedom)</div></div>
        <div><div class="signature-line font-bold text-[10px] uppercase text-gray-400">Datum</div></div>
    </div>
</form>

<script>
    // Försök tvinga fokus och utskrift
    function forcePrint() {
        window.focus();

        // Metod 1: Standard
        setTimeout(function() {
            try {
                if (!window.print()) {
                    // Metod 2: Fallback för vissa browsers i iframes
                    document.execCommand('print', false, null);
                }
            } catch (e) {
                // Metod 3: Sista utvägen
                window.print();
            }
        }, 100);
    }

    document.getElementById('btnPrint').addEventListener('click', forcePrint);

    document.getElementById('btnReset').addEventListener('click', function() {
        // Vi skippar confirm() helt eftersom det ofta blockeras i Google Sites sandlåda
        // och gör att inget händer när man klickar.
        const form = document.getElementById('gradeForm');
        const inputs = form.querySelectorAll('input');
        inputs.forEach(i => {
            if (i.type === 'checkbox') i.checked = false;
            else i.value = '';
        });
        form.querySelectorAll('textarea').forEach(t => t.value = '');
    });

    // Hjälp för Google Sites: Om användaren trycker Ctrl+P
    window.onkeydown = function(e) {
        if ((e.ctrlKey || e.metaKey) && e.keyCode == 80) {
            e.preventDefault();
            forcePrint();
        }
    };
</script>
</body>
</html>

