import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";

const MUNICIPALITY_ID = '0162'; // Danderyd
const KEY_KPIS = [
  { id: 'N00945', title: 'Invånarantal', unit: 'antal' },
  { id: 'N15033', title: 'Meritvärde åk 9', unit: 'poäng' },
  { id: 'N01951', title: 'Kommunal skattesats', unit: '%' },
  { id: 'N03901', title: 'Trygghetsindex', unit: 'index' }
];

interface KpiData {
  kpi: string;
  value: number;
  period: number;
}

const KoladaDashboard: React.FC = () => {
  const [data, setData] = useState<Record<string, any>>({});
  const [loading, setLoading] = useState(true);
  const [aiInsight, setAiInsight] = useState('');
  const [generatingInsight, setGeneratingInsight] = useState(false);

  useEffect(() => {
    fetchKoladaData();
  }, []);

  const fetchKoladaData = async () => {
    try {
      const kpiIds = KEY_KPIS.map(k => k.id).join(',');
      const response = await fetch(`https://api.kolada.se/v2/data/municipality/${MUNICIPALITY_ID}/kpi/${kpiIds}`);
      const json = await response.json();

      const mappedData: Record<string, any> = {};
      json.values.forEach((v: any) => {
        // Ta senaste året (perioden)
        if (!mappedData[v.kpi] || v.period > mappedData[v.kpi].period) {
          mappedData[v.kpi] = {
            value: v.values[0].value,
            period: v.period
          };
        }
      });
      setData(mappedData);
      setLoading(false);
    } catch (error) {
      console.error("Kunde inte hämta Kolada-data", error);
      setLoading(false);
    }
  };

  const generateAIInsight = async () => {
    setGeneratingInsight(true);
    setAiInsight('');

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const statsContext = KEY_KPIS.map(k => {
        const d = data[k.id];
        return `${k.title}: ${d?.value} (${d?.period})`;
      }).join(', ');

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Du är en expert på svensk kommunal ekonomi och statistik. Analysera följande nyckeltal för Danderyds kommun från Kolada: ${statsContext}. Ge en kort, insiktsfull sammanfattning på svenska (max 3 meningar) om vad detta innebär för kommunens utveckling.`,
      });

      setAiInsight(response.text || 'Kunde inte generera insikt.');
    } catch (error) {
      setAiInsight('Ett fel uppstod vid kommunikation med AI-tjänsten.');
    } finally {
      setGeneratingInsight(false);
    }
  };

  return (
