import React, { useState, useEffect, useCallback } from 'react';
import { GoogleGenAI } from "@google/genai";

const MUNICIPALITY_ID = '0162'; // Danderyd
const KEY_KPIS = [
  { id: 'N00945', title: 'Invånarantal', unit: 'antal' },
  { id: 'N15033', title: 'Meritvärde åk 9', unit: 'poäng' },
  { id: 'N01951', title: 'Kommunal skattesats', unit: '%' },
  { id: 'N03901', title: 'Trygghetsindex', unit: 'index' }
];

const KoladaDashboard: React.FC = () => {
  const [data, setData] = useState<Record<string, any>>({});
  const [loading, setLoading] = useState(true);
  const [aiInsight, setAiInsight] = useState('');
  const [generatingInsight, setGeneratingInsight] = useState(false);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  const fetchKoladaData = useCallback(async (isManual = false) => {
    setLoading(true);
    if (isManual) setAiInsight(''); // Rensa insikt vid manuell uppdatering

    try {
      const kpiIds = KEY_KPIS.map(k => k.id).join(',');
      // Använder cache: 'no-store' för att tvinga fram färsk data från API:et
      const response = await fetch(
        `https://api.kolada.se/v2/data/municipality/${MUNICIPALITY_ID}/kpi/${kpiIds}`,
        { cache: 'no-store' }
      );
      const json = await response.json();

      const mappedData: Record<string, any> = {};
      json.values.forEach((v: any) => {
        if (!mappedData[v.kpi] || v.period > mappedData[v.kpi].period) {
          mappedData[v.kpi] = {
            value: v.values[0].value,
            period: v.period
          };
        }
      });
      setData(mappedData);
      setLastUpdated(new Date());
    } catch (error) {
      console.error("Kunde inte hämta Kolada-data", error);
    } finally {
      setLoading(false);
    }
  }, []);

  // Hämta vid mount
  useEffect(() => {
    fetchKoladaData();

    // Auto-refresh när användaren kommer tillbaka till fliken
    const handleFocus = () => {
      fetchKoladaData();
    };
    window.addEventListener('focus', handleFocus);
    return () => window.removeEventListener('focus', handleFocus);
  }, [fetchKoladaData]);

  const generateAIInsight = async () => {
    setGeneratingInsight(true);
    setAiInsight('');

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const statsContext = KEY_KPIS.map(k => {
        const d = data[k.id];
        return `${k.title}: ${d?.value} (${d?.period})`;
      }).join(', ');

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Du är en expert på svensk kommunal ekonomi och statistik. Analysera följande nyckeltal för Danderyds kommun från Kolada: ${statsContext}. Ge en kort, insiktsfull sammanfattning på svenska (max 3 meningar) om vad detta innebär för kommunens utveckling. Var konkret.`,
      });

      setAiInsight(response.text || 'Kunde inte generera insikt.');
    } catch (error) {
      setAiInsight('Ett fel uppstod vid kommunikation med AI-tjänsten.');
    } finally {
      setGeneratingInsight(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto py-8 animate-fadeIn px-4 space-y-8">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-slate-200 pb-8">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <h1 className="text-4xl font-black text-slate-900 tracking-tight">Kommunanalys <span className="text-blue-600">Danderyd</span></h1>
            <button 
              onClick={() => fetchKoladaData(true)}
              disabled={loading}
              className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-full transition-all"
              title="Uppdatera data"
            >
              <svg className={`w-5 h-5 ${loading ? 'animate-spin text-blue-600' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path>
              </svg>
            </button>
          </div>
          <div className="flex items-center gap-4">
            <p className="text-slate-500 font-medium flex items-center gap-2 text-sm">
              <span className={`w-2 h-2 rounded-full ${loading ? 'bg-amber-500 animate-pulse' : 'bg-green-500'}`}></span>
              {loading ? 'Hämtar data...' : 'Live-data från Kolada API'}
            </p>
            {lastUpdated && !loading && (
              <span className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">
                Uppdaterad: {lastUpdated.toLocaleTimeString('sv-SE', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
              </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2 text-xs font-bold text-slate-400 uppercase tracking-widest bg-slate-100 px-4 py-2 rounded-full">
          Kommun-ID: 0162
        </div>
      </header>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {KEY_KPIS.map(kpi => (
